   private static NBTTagCompound decodeAndMergeKcmNbt(String base64Data, String displayName, int protLevel) {
      NBTTagCompound nbt;
      try {
         byte[] compressed = Base64.getDecoder().decode(base64Data);
         ByteArrayInputStream bais = new ByteArrayInputStream(compressed);
         nbt = CompressedStreamTools.readCompressed(bais);
      } catch (Exception e) {
         System.out.println("[RyoShop] WARNING: Failed to decode KCM armor NBT: " + e.getMessage());
         nbt = new NBTTagCompound();
      }

      NBTTagList enchList = new NBTTagList();
      NBTTagCompound ench = new NBTTagCompound();
      ench.setShort("id", (short)0);
      ench.setShort("lvl", (short)protLevel);
      enchList.appendTag(ench);
      nbt.setTag("ench", enchList);
      NBTTagCompound display = nbt.hasKey("display") ? nbt.getCompoundTag("display") : new NBTTagCompound();
      display.setString("Name", displayName);
      nbt.setTag("display", display);
      nbt.setBoolean("Unbreakable", true);
      return nbt;
   }

   private static CrateLootEntry kcmBundle(String displayName, String headB64, String chestB64, String legsB64, String bootsB64, int headProt, int chestProt, int legsProt, int bootsProt, double weight, ItemRarity rarity, String... tailSkinB64s) {
      String namePrefix = displayName.replaceAll("\\s*\\(.*\\).*", "").trim();
      String kcmPrefix = extractKcmPrefix(displayName);
      NBTTagCompound helmetNbt = decodeAndMergeKcmNbt(headB64, kcmPrefix + " Head", headProt);
      NBTTagCompound chestNbt = decodeAndMergeKcmNbt(chestB64, kcmPrefix + " Chest", chestProt);
      NBTTagCompound legsNbt = decodeAndMergeKcmNbt(legsB64, kcmPrefix + " Legs", legsProt);
      NBTTagCompound bootsNbt = decodeAndMergeKcmNbt(bootsB64, kcmPrefix + " Feet", bootsProt);
      List<CrateLootEntry.BundleItem> bundleItems = new ArrayList(Arrays.asList(new CrateLootEntry.BundleItem("minecraft:diamond_chestplate", 0, 1, chestNbt), new CrateLootEntry.BundleItem("minecraft:diamond_leggings", 0, 1, legsNbt), new CrateLootEntry.BundleItem("minecraft:diamond_boots", 0, 1, bootsNbt)));
      if (tailSkinB64s != null) {
         for(int i = 0; i < tailSkinB64s.length; ++i) {
            String tailName = kcmPrefix + " Tail" + (tailSkinB64s.length > 1 ? " " + (i + 1) : "");
            NBTTagCompound tailNbt = decodeTailSkinNbt(tailSkinB64s[i], tailName);
            bundleItems.add(new CrateLootEntry.BundleItem("armourers_workshop:skin", 0, 1, tailNbt));
         }
      }

      return new CrateLootEntry("minecraft:diamond_helmet", 0, 1, helmetNbt, weight, rarity, (String)null, displayName, bundleItems, (String)null);
   }

   private static NBTTagCompound decodeTailSkinNbt(String base64Data, String displayName) {
      NBTTagCompound nbt;
      try {
         byte[] compressed = Base64.getDecoder().decode(base64Data);
         ByteArrayInputStream bais = new ByteArrayInputStream(compressed);
         nbt = CompressedStreamTools.readCompressed(bais);
      } catch (Exception e) {
         System.out.println("[RyoShop] WARNING: Failed to decode tail skin NBT: " + e.getMessage());
         nbt = new NBTTagCompound();
      }

      NBTTagCompound display = nbt.hasKey("display") ? nbt.getCompoundTag("display") : new NBTTagCompound();
      display.setString("Name", displayName);
      nbt.setTag("display", display);
      return nbt;
   }

   private static String extractKcmPrefix(String displayName) {
      if (displayName.contains("1-Tail")) {
         return "1 Tails KCM";
      } else if (displayName.contains("2-Tail")) {
         return "2 Tails KCM";
      } else if (displayName.contains("3-Tail")) {
         return "3 Tails KCM";
      } else if (displayName.contains("4-Tail")) {
         return "4 Tails KCM";
      } else if (displayName.contains("5-Tail")) {
         return "5 Tails KCM";
      } else if (displayName.contains("6-Tail")) {
         return "6 Tails KCM";
      } else if (displayName.contains("7-Tail")) {
         return "7 Tails KCM";
      } else if (displayName.contains("8-Tail")) {
         return "8 Tails KCM";
      } else if (displayName.contains("9-Tail")) {
         return "9 Tails KCM";
      } else {
         return displayName.contains("10-Tail") ? "10 Tails KCM" : "KCM";
      }
   }

